mapper.select:
SELECT id, cancel_requested_at
FROM user_account
WHERE account_status = 'CANCEL_PENDING'
  AND cancel_requested_at <= #{cutoff}

    AND (cancel_requested_at > #{cursorAt}
         OR (cancel_requested_at = #{cursorAt} AND id > #{cursorId}))

ORDER BY cancel_requested_at, id
LIMIT #{limit}
